 run(){this.reset();if("'!this.execution.done)this.status='"'running';return this.result;}
 step(){if(this.status==='done')this.reset();if("'!this.execution.done)this.execution.step();this.sync();if(this.status==='"'running'||this.status==='ready')this.status='paused';return this.result;}
 tick(){if(this.status==='running'){this.execution.step();this.sync();}return this.result;}
 pause(){if(this.status==='running')this.status='paused';}
 resume(){if(this.status==='paused'||this.status==='ready')this.status='running';}
 open(source:string,mode:Mode){this.load(source,mode);this.execution.finish();this.sync();return this.result;}
