const browser=await chromium.launch({headless:true,args:['--no-sandbox']});
try{
 const page=await browser.newPage({viewport:{width:1440,height:1000}});const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto("'`http://localhost:${server.port}${prefix}`);await page.waitForFunction(()=>!!window.logomocja);
 const source='"'powtorz 4 [np 100 pw 90]';
 const r=await page.evaluate(s=>window.logomocja.open(s,'2d'),source);assert.equal(r.error,null);assert.equal(r.segments.length,4);assert.equal(await page.locator('#editor').inputValue(),source);
 await page.locator('#reset').click();assert.equal(await page.evaluate(()=>window.logomocja.controller.result.segments.length),0);
 await page.locator('#step').click();await page.locator('#step').click();assert.equal(await page.evaluate(()=>window.logomocja.controller.result.segments.length),1);
 await page.locator('#run').click();await page.waitForFunction(()=>window.logomocja.controller.status==='done');assert.equal(await page.evaluate(()=>window.logomocja.controller.result.segments.length),4);
 assert.deepEqual(errors,[]);
 console.log('PASS: browser open, reset, step and repeated execution agree with run.');
 const deep=await page.evaluate(()=>window.logomocja.run('np '+'('.repeat(4900)+'2'+')'.repeat(4900),'2d'));
 assert.equal(deep.error,null);assert.equal(deep.segments.length,1);
 console.log('PASS: maximum-depth expression stays within language limits in Chromium.');
}finally{await browser.close();server.stop();}
EOF
