export type Mode = "2d" | "3d";
export type Vec = [number, number, number];
export type Segment = { from: Vec; to: Vec; color: string; width: number };
export type LogoError = { message: string; line: number; column: number };
export type Result = { segments: Segment[]; error: LogoError | null };
type Token = {
  v: string;
  line: number;
  column: number;
  start: number;
  end: number;
  type: string;
};
export const aliases: Record<string, string> = {};
const groups: Record<string, string> = {
  fd: "np naprzod naprzód fd forward",
  bk: "ws wstecz bk back",
  rt: "pw prawo rt right",
  lt: "lw lewo lt left",
  pu: "pod podnies podnieś pu penup",
  pd: "opu opusc opuść pd pendown",
  color: "kolor color",
  width: "grubosc grubość width",
  repeat: "powtorz powtórz repeat",
  let: "niech let",
  if: "jeśli jesli if",
  ifelse: "jeżeli jezeli ifelse",
  stop: "stop",
  home: "dom home",
  cs: "czyść czysc cs clearscreen",
  pitchup: "gora góra pitchup",
  pitchdown: "dol dół pitchdown",
  rollright: "pp przechylprawo rr rollright",
  rollleft: "pl przechyllewo rl rollleft",
  to: "oto to",
  end: "już juz end",
  repcount: "nrpowt repcount",
};
for (const [key, names] of Object.entries(groups))
  for (const n of names.split(" ")) aliases[n] = key;
class Fault extends Error {
  info: LogoError;
  constructor(t: Token, message: string) {
    super(message);
    this.info = { message, line: t.line, column: t.column };
  }
}
function fail(t: Token, message: string): never {
  throw new Fault(t, message);
}
function lex(source: string): Token[] {
  let i = 0,
    line = 1,
    column = 1;
  const out: Token[] = [];
  const add = (v: string, type: string) => {
    out.push({
      v: v.toLowerCase(),
      type,
      line,
      column,
      start: i,
      end: i + v.length,
    });
    i += v.length;
    column += v.length;
  };
  while (i < source.length) {
    const c = source[i];
    if (c === "\n") {
      i++;
      line++;
      column = 1;
      continue;
    }
    if (/\s/.test(c)) {
      i++;
      column++;
      continue;
    }
    if (c === ";") {
      while (i < source.length && source[i] !== "\n") {
        i++;
        column++;
      }
      continue;
    }
    const rest = source.slice(i);
    let m;
    if (c === '"') {
      const end = source.indexOf('"', i + 1);
      if (end < 0 || source.slice(i, end).includes("\n"))
        fail(
          { v: c, line, column, start: i, end: i + 1, type: "string" },
          'Niedomknięty zapis koloru. Użyj "#16866a".',
        );
      add(source.slice(i, end + 1), "string");
    } else if ((m = rest.match(/^(?:\d+(?:\.\d*)?|\.\d+)/))) {
      const v = m[0];
      if (/[\p{L}_.\d]/u.test(rest[v.length] || " "))
        fail(
          { v, line, column, start: i, end: i + v.length, type: "number" },
          "Niepoprawna liczba. Użyj zapisu dziesiętnego, np. 12.5.",
        );
      add(v, "number");
    } else if ((m = rest.match(/^:?[\p{L}_][\p{L}\p{N}_]*/u)))
      add(m[0], "name");
    else if ((m = rest.match(/^(?:<=|>=|<>|[+\-*/<>=\[\](),:])/)))
      add(m[0], "symbol");
    else
      fail(
        { v: c, line, column, start: i, end: i + 1, type: "symbol" },
        `Nieznany znak „${c}”.`,
      );
    if (out.length > 10000)
      fail(out[out.length - 1], "Przekroczono limit 10 000 tokenów.");
  }
  out.push({ v: "", type: "eof", line, column, start: i, end: i });
  return out;
}
type Expr = {
  t: Token;
  kind: "num" | "unary" | "binary" | "name" | "rep";
  value?: number;
  op?: string;
  left?: Expr;
  right?: Expr;
  name?: string;
};
type Node = {
  t: Token;
  cmd: string;
  args: Expr[];
  body?: Node[];
  other?: Node[];
  color?: string;
  name?: string;
  comparison?: string;
};
type Proc = {
  t: Token;
  name: string;
  params: string[];
  body: Node[];
  tokens: Token[];
};
type Program = { body: Node[]; procs: Map<string, Proc> };
const key = (t: Token) => aliases[t.v] || t.v;
const nameOf = (t: Token) => t.v.replace(/^:/, "");
class Parser {
  i = 0;
  depth = 0;
  repeatDepth = 0;
  params = new Set<string>();
  known = new Set<string>();
  procs = new Map<string, Proc>();
  constructor(
    public tokens: Token[],
    public source: string,
    public mode: Mode,
  ) {}
  peek() {
    return this.tokens[this.i];
  }
  take() {
    return this.tokens[this.i++];
  }
  expr(fallback: Token): Expr {
    const values: Expr[] = [];
    const ops: {
      t: Token;
      kind: "unary" | "binary" | "open";
      priority: number;
    }[] = [];
    let expected = true,
      opened = 0;
    const apply = () => {
      const op = ops.pop()!;
      const right = values.pop()!;
      if (op.kind === "unary")
